-- Generated by tools/gen_upstream_test.py from OpenCC's test/testcases/testcases.json.
-- Every upstream golden case must convert exactly as OpenCC itself does.
CREATE TEMP TABLE upstream_case (id text, config text, input text, expected text);

SELECT count(*) AS cases, count(DISTINCT config) AS configs FROM upstream_case;

SELECT config, count(*) AS cases,
       count(*) FILTER (WHERE opencc.convert(input, config) <> expected) AS failures
  FROM upstream_case GROUP BY config ORDER BY config;

SELECT id, config, input, expected, opencc.convert(input, config) AS actual
  FROM upstream_case
 WHERE opencc.convert(input, config) <> expected
 ORDER BY id, config;
